from dataclasses import dataclass
from pathlib import Path
import ast

@dataclass(frozen=True, slots=True)
class ImportRecord:
    module: str
    alias: str | None
    path: Path

def extract_imports(src: str) -> list[ImportRecord]:
    tree = ast.parse(src)
    records: list[ImportRecord] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                records.append(ImportRecord(
                    module=alias.name,
                    alias=alias.asname,
                    path=Path(src).resolve().as_posix(),
                ))
        elif isinstance(node, ast.ImportFrom):
            module = node.module or ""
            for alias in node.names:
                records.append(ImportRecord(module, alias.asname, Path(src).resolve().as_posix()))
    return records
